["sparkRotationMode"] = "AUTO",
["icon"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["names"] = {
},
["events"] = "CHALLENGE_MODE_START\nUNIT_AURA\nPLAYER_REGEN_DISABLED\nPLAYER_REGEN_ENABLED\nPLAYER_DEAD\nPLAYER_ALIVE\nPLAYER_UNGHOST\nOPTIONS\nTRAIT_CONFIG_UPDATED CHALLENGE_MODE_START\nENCOUNTER_START",
["custom_type"] = "stateupdate",
["check"] = "event",
["custom"] = "------------------------------------------------------------------------------\n-- Awakening-Storm simple counter (0-8 per deck) with optional countdown mode\n-- Exposes: AwakenCount (number), CountDownFrom8 (bool)\n------------------------------------------------------------------------------\n\nfunction(allstates, event, unit, ...)\n    ----------------------------------------------------------------\n    -- helpers & flags\n    ----------------------------------------------------------------\n    local DBG  = aura_env.config.enable_debug\n    local nowP = GetTimePreciseSec()\n    \n    local ASID  = 462131      -- Awakening-Storm (buff stacks)\n    local ASCID = 114051      -- Ascendance\n    local tierW = aura_env.tierWindow or 0.150   -- 150 ms Tier window\n    \n    -- raw up-count (0..16), we keep logic unchanged and map to display later\n    aura_env.saved                 = aura_env.saved or {}\n    aura_env.saved.AwakenCount     = aura_env.saved.AwakenCount or 0\n    aura_env.baselineSet           = aura_env.baselineSet or false\n    aura_env.prevStackCount        = aura_env.prevStackCount or 0\n    aura_env.prevAscPresent        = aura_env.prevAscPresent or false\n    aura_env.prevAscExpire         = aura_env.prevAscExpire or 0\n    aura_env.inCombat              = (aura_env.inCombat ~= nil) and aura_env.inCombat or UnitAffectingCombat(\"player\")\n    \n    -- read the UI option; also honor aura_env.countDownFrom8 if set in On Init\n    local countDown = not not (aura_env.countDownFrom8 or aura_env.config.countdown_from_8)\n    \n    local function toDisplayCount(raw)\n        raw = raw or 0\n        -- show within current deck (mod 8). If countdown: 8,7,...,1,0\n        local within = raw % 8\n        return countDown and (8 - within) or raw\n    end\n    \n    ----------------------------------------------------------------\n    -- ensure state row exists\n    ----------------------------------------------------------------\n    if not allstates[\"\"] then\n        allstates[\"\"] = { show = true, changed = true }\n        local st = allstates[\"\"]\n        st.AwakenCount    = toDisplayCount(aura_env.saved.AwakenCount)\n        st.CountDownFrom8 = countDown\n    end\n    local st = allstates[\"\"]; st.changed = false\n    \n    ----------------------------------------------------------------\n    -- hard resets (death, spec swap, talents, raid-boss pull, M+ start)\n    ----------------------------------------------------------------\n    local diffID = (event == \"ENCOUNTER_START\") and select(3, GetInstanceInfo()) or 0\n    if event == \"PLAYER_DEAD\"\n    or event == \"PLAYER_SPECIALIZATION_CHANGED\"\n    or event == \"PLAYER_TALENT_UPDATE\"\n    or event == \"TRAIT_CONFIG_UPDATED\"\n    or event == \"TRAIT_CONFIG_LIST_UPDATED\"\n    or event == \"CHALLENGE_MODE_START\"\n    or (event == \"ENCOUNTER_START\" and diffID >= 14 and diffID <= 17) then\n        aura_env.saved.AwakenCount = 0\n        aura_env.baselineSet       = false\n        st.AwakenCount             = toDisplayCount(0)\n        st.CountDownFrom8          = countDown\n        st.changed                 = true\n        if DBG then print(\"|cffff5555[AS]|r Hard reset (\"..event..\")\") end\n        return allstates\n    end\n    \n    ----------------------------------------------------------------\n    -- simple bookkeeping\n    ----------------------------------------------------------------\n    if event == \"PLAYER_REGEN_DISABLED\" then aura_env.inCombat = true;  return\n    elseif event == \"PLAYER_REGEN_ENABLED\" then aura_env.inCombat = false; return\n    elseif event == \"PLAYER_ALIVE\" or event == \"PLAYER_UNGHOST\" then return\n    elseif event == \"OPTIONS\" then\n        -- user toggled the option: refresh the flag and the display\n        countDown = not not (aura_env.countDownFrom8 or aura_env.config.countdown_from_8)\n        st.AwakenCount    = toDisplayCount(aura_env.saved.AwakenCount)\n        st.CountDownFrom8 = countDown\n        st.changed        = true\n        return true\n    end\n    \n    ----------------------------------------------------------------\n    -- UNIT_AURA (player only)\n    ----------------------------------------------------------------\n    if event ~= \"UNIT_AURA\" or unit ~= \"player\" then return end\n    \n    local AS  = C_UnitAuras.GetPlayerAuraBySpellID(ASID)\n    local vStacks = AS and (AS.applications or 1) or 0\n    \n    local Asc    = C_UnitAuras.GetPlayerAuraBySpellID(ASCID)\n    local ascNow = Asc ~= nil\n    local ascExp = Asc and Asc.expirationTime or 0\n    \n    ----------------------------------------------------------------\n    -- first baseline\n    ----------------------------------------------------------------\n    if not aura_env.baselineSet then\n        aura_env.prevStackCount    = vStacks\n        aura_env.prevAscPresent    = ascNow\n        aura_env.prevAscExpire     = ascExp\n        aura_env.saved.AwakenCount = vStacks\n        st.AwakenCount             = toDisplayCount(vStacks)\n        st.CountDownFrom8          = countDown\n        st.changed                 = true\n        aura_env.baselineSet       = true\n        return allstates\n    end\n    \n    ----------------------------------------------------------------\n    -- visible stack gain\n    ----------------------------------------------------------------\n    if vStacks > aura_env.prevStackCount then\n        aura_env.saved.AwakenCount =\n        aura_env.saved.AwakenCount + (vStacks - aura_env.prevStackCount)\n        if aura_env.saved.AwakenCount > 16 then\n            aura_env.saved.AwakenCount = 0\n            if DBG then print(\"|cffffaaaa[AS]|r reset (count > 16)\") end\n        end\n        st.AwakenCount    = toDisplayCount(aura_env.saved.AwakenCount)\n        st.CountDownFrom8 = countDown\n        st.changed        = true\n    end\n    \n    ----------------------------------------------------------------\n    -- hidden consume (buff vanishes) → record Storm-fade stamp\n    ----------------------------------------------------------------\n    if vStacks == 0 and aura_env.prevStackCount > 0 then\n        aura_env.lastStormFadeP = nowP\n        if aura_env.inCombat then\n            aura_env.saved.AwakenCount =\n            aura_env.saved.AwakenCount + (4 - aura_env.prevStackCount)\n            if aura_env.saved.AwakenCount > 16 then\n                aura_env.saved.AwakenCount = 0\n                if DBG then print(\"|cffffaaaa[AS]|r reset (count > 16)\") end\n            end\n            st.AwakenCount    = toDisplayCount(aura_env.saved.AwakenCount)\n            st.CountDownFrom8 = countDown\n            st.changed        = true\n        else\n            aura_env.saved.AwakenCount = 0\n            st.AwakenCount             = toDisplayCount(0)\n            st.CountDownFrom8          = countDown\n            st.changed                 = true\n            aura_env.baselineSet       = false\n        end\n        if DBG then\n            print(string.format(\"|cff99ff99[AS]|r vanish → %d\", aura_env.saved.AwakenCount))\n        end\n    end\n    \n    ----------------------------------------------------------------\n    -- Ascendance appears / refreshes (Tier detection)\n    ----------------------------------------------------------------\n    local ascChange =\n    (ascNow and not aura_env.prevAscPresent) or\n    (ascNow and aura_env.prevAscPresent and ascExp > aura_env.prevAscExpire + 0.05)\n    \n    if ascChange then\n        aura_env.lastAscGainP = nowP\n        local dtFade = nowP - (aura_env.lastStormFadeP or 9e9)\n        \n        -- Tier if fade came BEFORE Asc and within tierW\n        if dtFade >= 0 and dtFade <= tierW then\n            aura_env.saved.AwakenCount = 0\n            st.AwakenCount             = toDisplayCount(0)\n            st.CountDownFrom8          = countDown\n            st.changed                 = true\n            if DBG then\n                print(string.format(\"|cff00ff00[AS]|r Asc→Tier reset (Δ=%.3f)\", dtFade))\n            end\n        elseif DBG then\n            print(string.format(\"|cffffaaaa[AS]|r Asc ignored (ΔFade=%.3f)\", dtFade))\n        end\n    end\n    \n    ----------------------------------------------------------------\n    -- update trackers\n    ----------------------------------------------------------------\n    aura_env.prevStackCount = vStacks\n    aura_env.prevAscPresent = ascNow\n    aura_env.prevAscExpire  = ascExp\n    \n    return st.changed and allstates or nil\nend",
["spellIds"] = {
},
["customVariables"] = "{\n    AwakenCount    = { type = \"number\" },\n    CountDownFrom8 = { type = \"bool\" },\n}",
