["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "{\n    Stacks = {\n        type = \"number\",\n    },\n    \n}\n\n\n\n",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["events"] = "WA_DELAYED_PLAYER_ENTERING_WORLD CLEU:SPELL_AURA_APPLIED CLEU:SPELL_AURA_APPLIED_DOSE PLAYER_DEAD TRAIT_CONFIG_UPDATED CHALLENGE_MODE_START ENCOUNTER_START",
["spellIds"] = {
},
["custom"] = "function(allstates, event, isLogin, subevent, _, sourceGUID, _, _, _, _, _, _, _, spellId, ...)\n    \n    if event == \"WA_DELAYED_PLAYER_ENTERING_WORLD\" or event == \"STATUS\" or event == \"OPTIONS\" then\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            Stacks = 0,\n        }\n        \n        if isLogin then\n            aura_env.saved = {}\n        end\n        \n        if aura_env.saved.state and (aura_env.saved.state.Stacks ~= nil) then \n            allstates[\"\"].Stacks = aura_env.saved.state.Stacks\n            if (allstates[\"\"].Stacks >= aura_env.maxStacks) then \n                allstates[\"\"].Stacks = 0 \n            end\n        else\n            aura_env.saved.state = {}\n        end\n        \n        return true\n        \n    elseif event == \"CHALLENGE_MODE_START\" or event == \"ENCOUNTER_START\" or event == \"TRAIT_CONFIG_UPDATED\" or event == \"PLAYER_DEAD\" then\n        \n        if event == \"ENCOUNTER_START\" and sourceGUID == 5 then return end --groupSize, do not reset on m+ bosses\n        allstates[\"\"].changed = true\n        allstates[\"\"].Stacks = 0\n        aura_env.saved.state.Stacks = allstates[\"\"].Stacks\n        \n        return true\n        \n    elseif (event == \"COMBAT_LOG_EVENT_UNFILTERED\" and sourceGUID == WeakAuras.myGUID) then\n        \n        if ((subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_APPLIED_DOSE\") and (spellId == aura_env.asBuff)) then \n            \n            allstates[\"\"].changed = true\n            \n            aura_env.lastASTime = GetTime()\n            allstates[\"\"].Stacks = allstates[\"\"].Stacks + 1\n            \n            \n            if (allstates[\"\"].Stacks >= aura_env.maxStacks) then\n                allstates[\"\"].Stacks = 0\n            end\n            \n            aura_env.saved.state.Stacks = allstates[\"\"].Stacks\n            \n            return true\n            \n        end\n    end\n    \nend",
